extern crate std;

use base64::{engine::general_purpose::STANDARD, Engine};
use ed25519_dalek::{Signer, SigningKey};
use p256::ecdsa::Signature;
use serde::Deserialize;
use soroban_sdk::{Bytes, BytesN, Env};
use std::{println, string::String, vec::Vec};

use crate::{PasskeyError, PasskeyVerifierClient};

// The contract compiled to WASM (`stellar contract build`), so costs include the VM.
const WASM: &[u8] = include_bytes!("../target/wasm32v1-none/release/passkey_verify.wasm");

/// Real output of a Chrome virtual authenticator, generated by the browser (see assertions.json).
#[derive(Deserialize)]
struct Fixture {
    spki: String,
    assertions: Vec<Assertion>,
}

#[derive(Deserialize, Clone)]
struct Assertion {
    challenge: String,
    #[serde(rename = "authenticatorData")]
    authenticator_data: String,
    #[serde(rename = "clientDataJSON")]
    client_data_json: String,
    signature: String,
}

fn fixture() -> Fixture {
    serde_json::from_str(include_str!("../assertions.json")).unwrap()
}

fn b64(text: &str) -> Vec<u8> {
    STANDARD.decode(text).unwrap()
}

/// The uncompressed SEC-1 point: the last 65 bytes of the 91-byte SPKI.
fn public_key(env: &Env, fx: &Fixture) -> BytesN<65> {
    let spki = b64(&fx.spki);
    BytesN::from_array(env, spki[spki.len() - 65..].try_into().unwrap())
}

fn rp_id_hash(env: &Env) -> BytesN<32> {
    env.crypto().sha256(&Bytes::from_slice(env, b"localhost")).to_bytes()
}

struct Case<'a> {
    client: PasskeyVerifierClient<'a>,
    env: Env,
    fx: Fixture,
}

fn setup<'a>() -> Case<'a> {
    let env = Env::default();
    let id = env.register(WASM, ());
    Case { client: PasskeyVerifierClient::new(&env, &id), env, fx: fixture() }
}

impl Case<'_> {
    fn call(&self, a: &Assertion, signature: [u8; 64]) -> Result<Result<(), soroban_sdk::ConversionError>, Result<PasskeyError, soroban_sdk::InvokeError>> {
        self.client.try_verify(
            &public_key(&self.env, &self.fx),
            &rp_id_hash(&self.env),
            &BytesN::from_array(&self.env, &b64(&a.challenge).try_into().unwrap()),
            &Bytes::from_slice(&self.env, &b64(&a.authenticator_data)),
            &Bytes::from_slice(&self.env, &b64(&a.client_data_json)),
            &BytesN::from_array(&self.env, &signature),
        )
    }
}

/// DER (what WebAuthn returns) to the 64-byte r||s form Soroban expects, plus whether s was already low.
fn compact(der: &[u8]) -> ([u8; 64], bool) {
    let sig = Signature::from_der(der).unwrap();
    let was_low = sig.normalize_s().is_none();
    (sig.to_bytes().into(), was_low)
}

fn low_s(der: &[u8]) -> [u8; 64] {
    let sig = Signature::from_der(der).unwrap();
    sig.normalize_s().unwrap_or(sig).to_bytes().into()
}

/// The same signature with s replaced by n - s: still mathematically valid ECDSA, but high-S.
fn high_s(der: &[u8]) -> [u8; 64] {
    let sig = low_s(der);
    let sig = Signature::from_slice(&sig).unwrap();
    let (r, s) = sig.split_scalars();
    Signature::from_scalars(r.to_bytes(), (-*s).to_bytes()).unwrap().to_bytes().into()
}

#[test]
fn real_browser_assertions_verify_once_normalized_to_low_s() {
    let t = setup();
    let (mut raw_ok, mut raw_high_s_rejected, mut high_variant_rejected) = (0, 0, 0);
    for a in &t.fx.assertions {
        let der = b64(&a.signature);
        let (raw, was_low) = compact(&der);

        // Straight from the authenticator: passes only if the authenticator happened to emit low-S.
        let raw_result = t.call(a, raw);
        assert_eq!(raw_result.is_ok(), was_low, "raw signature: low-S={was_low}");
        if raw_result.is_ok() {
            raw_ok += 1;
        } else {
            raw_high_s_rejected += 1;
        }

        // Normalized to low-S: always passes.
        assert_eq!(t.call(a, low_s(&der)), Ok(Ok(())));
        // The mirrored high-S form of the same signature never does.
        assert!(t.call(a, high_s(&der)).is_err());
        high_variant_rejected += 1;
    }
    println!(
        "\nREAL ASSERTIONS ({}): raw signature accepted {raw_ok}, rejected as high-S {raw_high_s_rejected}; \
         low-S normalized accepted {}; mirrored high-S rejected {high_variant_rejected}",
        t.fx.assertions.len(),
        t.fx.assertions.len(),
    );
    assert!(raw_high_s_rejected > 0, "expected some real signatures to be high-S (about half)");
}

#[test]
fn rejects_each_kind_of_bad_assertion() {
    let t = setup();
    let a = t.fx.assertions[0].clone();
    let sig = low_s(&b64(&a.signature));
    let call_with = |mutate: &dyn Fn(&mut Vec<u8>, &mut Vec<u8>, &mut Vec<u8>)| {
        let (mut auth, mut client, mut challenge) = (b64(&a.authenticator_data), b64(&a.client_data_json), b64(&a.challenge));
        mutate(&mut auth, &mut client, &mut challenge);
        t.client.try_verify(
            &public_key(&t.env, &t.fx),
            &rp_id_hash(&t.env),
            &BytesN::from_array(&t.env, &challenge.try_into().unwrap()),
            &Bytes::from_slice(&t.env, &auth),
            &Bytes::from_slice(&t.env, &client),
            &BytesN::from_array(&t.env, &sig),
        )
    };

    assert_eq!(call_with(&|_, _, _| {}), Ok(Ok(())));
    // Signed for another payload (replay against a different authorization).
    assert_eq!(call_with(&|_, _, c| c[0] ^= 1), Err(Ok(PasskeyError::ChallengeMismatch)));
    // Wrong relying party (an assertion made for another site).
    assert_eq!(call_with(&|auth, _, _| auth[0] ^= 1), Err(Ok(PasskeyError::RpMismatch)));
    // Missing user presence / user verification flags.
    assert_eq!(call_with(&|auth, _, _| auth[32] &= !0x01), Err(Ok(PasskeyError::UserNotPresent)));
    assert_eq!(call_with(&|auth, _, _| auth[32] &= !0x04), Err(Ok(PasskeyError::UserNotVerified)));
    // Truncated authenticator data, empty and oversized client data.
    assert_eq!(call_with(&|auth, _, _| auth.truncate(36)), Err(Ok(PasskeyError::BadAuthenticatorData)));
    assert_eq!(call_with(&|_, client, _| client.clear()), Err(Ok(PasskeyError::BadClientData)));
    assert_eq!(call_with(&|_, client, _| client.resize(600, b' ')), Err(Ok(PasskeyError::BadClientData)));
    // A registration ceremony ("webauthn.create") must not be accepted as an assertion.
    assert_eq!(
        call_with(&|_, client, _| {
            let text = String::from_utf8(client.clone()).unwrap().replace("webauthn.get", "webauthn.cret");
            *client = text.into_bytes();
        }),
        Err(Ok(PasskeyError::BadClientData))
    );
    // Any change to the signed bytes (here the origin) breaks the signature, which traps.
    let tampered = call_with(&|_, client, _| {
        let text = String::from_utf8(client.clone()).unwrap().replace("localhost", "localhosx");
        *client = text.into_bytes();
    });
    assert!(tampered.is_err() && !matches!(tampered, Err(Ok(_))), "signature failure should be a trap, got {tampered:?}");
}

#[test]
fn another_passkey_cannot_sign_for_this_one() {
    let t = setup();
    let a = &t.fx.assertions[0];
    let other = std::array::from_fn::<u8, 65, _>(|i| if i == 0 { 4 } else { i as u8 });
    let result = t.client.try_verify(
        &BytesN::from_array(&t.env, &other),
        &rp_id_hash(&t.env),
        &BytesN::from_array(&t.env, &b64(&a.challenge).try_into().unwrap()),
        &Bytes::from_slice(&t.env, &b64(&a.authenticator_data)),
        &Bytes::from_slice(&t.env, &b64(&a.client_data_json)),
        &BytesN::from_array(&t.env, &low_s(&b64(&a.signature))),
    );
    assert!(result.is_err());
}

#[test]
fn measure_cost_against_the_ed25519_check_the_account_uses_today() {
    let t = setup();
    let a = &t.fx.assertions[0];
    let sig = low_s(&b64(&a.signature));

    t.call(a, sig).unwrap().unwrap();
    let full = t.env.cost_estimate().resources();

    // The bytes the passkey really signed, so only the hashing and the host call are measured.
    let client_hash = t.env.crypto().sha256(&Bytes::from_slice(&t.env, &b64(&a.client_data_json)));
    let mut message = Bytes::from_slice(&t.env, &b64(&a.authenticator_data));
    message.append(&Bytes::from(client_hash.to_bytes()));
    t.client.crypto_only(&public_key(&t.env, &t.fx), &message, &BytesN::from_array(&t.env, &sig));
    let crypto_only = t.env.cost_estimate().resources();

    let key = SigningKey::from_bytes(&[1; 32]);
    let msg = [9u8; 32];
    let ed_sig = key.sign(&msg).to_bytes();
    t.client.ed25519_only(
        &BytesN::from_array(&t.env, key.verifying_key().as_bytes()),
        &Bytes::from_slice(&t.env, &msg),
        &BytesN::from_array(&t.env, &ed_sig),
    );
    let ed = t.env.cost_estimate().resources();

    const LIMIT: u64 = 400_000_000;
    println!(
        "\nCPU instructions (limit per transaction {LIMIT}):\n  full passkey check   {:>12}  ({:.1}% of limit)  mem {} B\n  secp256r1 + sha256   {:>12}  (crypto host calls only)\n  ed25519 (today)      {:>12}",
        full.instructions,
        full.instructions as f64 * 100.0 / LIMIT as f64,
        full.mem_bytes,
        crypto_only.instructions,
        ed.instructions,
    );
    assert!((full.instructions as u64) < LIMIT / 2, "passkey check should use well under half the budget");
}
